insert into public.topics (id, unit_id, slug, position, title, tagline, learning_objectives, status, is_demo) values
  ('00000000-0000-4000-8000-060000000001', '00000000-0000-4000-8000-050000000001', 'functions-and-graphs', 1, 'Functions & graphs', 'Start by seeing the pattern.', array['Explain what makes a rule a function.', 'Find the domain of simple functions.', 'Read inputs and outputs from a graph or table.']::text[], 'published', true),
  ('00000000-0000-4000-8000-060000000002', '00000000-0000-4000-8000-050000000001', 'limits-and-continuity', 2, 'Limits & continuity', 'What happens as you get closer?', array['Describe a limit in your own words.', 'Evaluate limits of polynomials by substitution.', 'State the three conditions for continuity at a point.']::text[], 'published', true),
  ('00000000-0000-4000-8000-060000000003', '00000000-0000-4000-8000-050000000002', 'derivatives', 1, 'Derivatives', 'Measure how fast things change.', array['Interpret a derivative as a rate of change.', 'Apply the power rule to polynomial terms.', 'Explain why the derivative of a constant is zero.']::text[], 'published', true);
insert into public.lessons (id, topic_id, kind, title, source_id, status, is_demo) values
  ('00000000-0000-4000-8000-070000000001', '00000000-0000-4000-8000-060000000001', 'full', 'Functions & graphs: full lesson', '00000000-0000-4000-8000-0c0000000001', 'published', true),
  ('00000000-0000-4000-8000-070000000002', '00000000-0000-4000-8000-060000000001', 'quick_notes', 'Functions & graphs: quick notes', '00000000-0000-4000-8000-0c0000000001', 'published', true),
  ('00000000-0000-4000-8000-070000000003', '00000000-0000-4000-8000-060000000002', 'full', 'Limits & continuity: full lesson', '00000000-0000-4000-8000-0c0000000001', 'published', true),
  ('00000000-0000-4000-8000-070000000004', '00000000-0000-4000-8000-060000000002', 'quick_notes', 'Limits & continuity: quick notes', '00000000-0000-4000-8000-0c0000000001', 'published', true),
  ('00000000-0000-4000-8000-070000000005', '00000000-0000-4000-8000-060000000003', 'full', 'Derivatives: full lesson', '00000000-0000-4000-8000-0c0000000001', 'published', true),
  ('00000000-0000-4000-8000-070000000006', '00000000-0000-4000-8000-060000000003', 'quick_notes', 'Derivatives: quick notes', '00000000-0000-4000-8000-0c0000000001', 'published', true);
insert into public.lesson_sections (id, lesson_id, position, kind, heading, body, data) values
  ('00000000-0000-4000-8000-080000000002', '00000000-0000-4000-8000-070000000001', 1, 'text', 'The main idea', 'A function is a machine: give it one input and it produces one output. For example, the rule f(x) = 2x + 1 doubles the input then adds one.', null),
  ('00000000-0000-4000-8000-080000000003', '00000000-0000-4000-8000-070000000001', 2, 'text', 'How it works', 'To read a graph, look at the horizontal axis for inputs and the vertical axis for outputs. Each point (x, y) shows the input and its output.', null),
  ('00000000-0000-4000-8000-080000000004', '00000000-0000-4000-8000-070000000001', 3, 'text', 'Look a little closer', 'A value is only in the domain if the rule is defined there. For example, f(x) = 1/x cannot take x = 0, since division by zero is not allowed.', null),
  ('00000000-0000-4000-8000-080000000005', '00000000-0000-4000-8000-070000000001', 4, 'text', 'Try it yourself', 'Make a small table before drawing a graph: for f(x) = 2x + 1, the input values 0, 1 and 2 produce 1, 3 and 5. Plot the points and connect them with a straight line.', null),
  ('00000000-0000-4000-8000-080000000006', '00000000-0000-4000-8000-070000000001', 5, 'text', 'Before you continue', 'Check your understanding: how would the table change if the rule were f(x) = 2x - 1? Compare the two graphs. They have the same steepness, but different vertical intercepts.', null),
  ('00000000-0000-4000-8000-080000000001', '00000000-0000-4000-8000-070000000001', 6, 'diagram', 'Look at the rule: f(x) = 2x + 1', 'Each row of the table gives one point on the line.', '{"type":"function_plot","rule":"f(x) = 2x + 1","points":[[0,1],[1,3],[2,5],[3,7]],"caption":"Each row gives one point on the line."}'::jsonb),
  ('00000000-0000-4000-8000-080000000007', '00000000-0000-4000-8000-070000000001', 7, 'worked_example', 'Worked example', 'f(x) = 2x + 1. When x = 3, f(3) = 2(3) + 1 = 7.', null),
  ('00000000-0000-4000-8000-080000000008', '00000000-0000-4000-8000-070000000002', 1, 'key_point', null, 'A function gives one output for every permitted input.', null),
  ('00000000-0000-4000-8000-080000000009', '00000000-0000-4000-8000-070000000002', 2, 'key_point', null, 'The domain is the set of valid inputs; the range is the set of outputs.', null),
  ('00000000-0000-4000-8000-08000000000a', '00000000-0000-4000-8000-070000000002', 3, 'key_point', null, 'A graph shows how output changes when input changes.', null),
  ('00000000-0000-4000-8000-08000000000b', '00000000-0000-4000-8000-070000000002', 4, 'worked_example', 'Worked example', 'f(x) = 2x + 1. When x = 3, f(3) = 7.', null),
  ('00000000-0000-4000-8000-08000000000c', '00000000-0000-4000-8000-070000000003', 1, 'text', 'The main idea', 'Imagine walking toward a door. A limit asks where you are heading as you approach it—not necessarily what happens at the exact door.', null),
  ('00000000-0000-4000-8000-08000000000d', '00000000-0000-4000-8000-070000000003', 2, 'text', 'How it works', 'For polynomials, you can usually find a limit by substituting the target value. For expressions with 0/0, first simplify or factor if valid.', null),
  ('00000000-0000-4000-8000-08000000000e', '00000000-0000-4000-8000-070000000003', 3, 'text', 'Look a little closer', 'Continuity means there is no break at the point: the function is defined, the limit exists, and the two values match.', null),
  ('00000000-0000-4000-8000-08000000000f', '00000000-0000-4000-8000-070000000003', 4, 'worked_example', 'Worked example', 'lim (x → 2) (x + 3) = 2 + 3 = 5.', null),
  ('00000000-0000-4000-8000-080000000010', '00000000-0000-4000-8000-070000000004', 1, 'key_point', null, 'A limit describes the value a function approaches near an input.', null),
  ('00000000-0000-4000-8000-080000000011', '00000000-0000-4000-8000-070000000004', 2, 'key_point', null, 'The function does not always need to equal the limit at that point.', null),
  ('00000000-0000-4000-8000-080000000012', '00000000-0000-4000-8000-070000000004', 3, 'key_point', null, 'A function is continuous when its value and its limit agree.', null),
  ('00000000-0000-4000-8000-080000000013', '00000000-0000-4000-8000-070000000004', 4, 'worked_example', 'Worked example', 'lim (x → 2) (x + 3) = 5.', null),
  ('00000000-0000-4000-8000-080000000014', '00000000-0000-4000-8000-070000000005', 1, 'text', 'The main idea', 'The slope of a curve at a point tells you how quickly its y-value is changing there.', null),
  ('00000000-0000-4000-8000-080000000015', '00000000-0000-4000-8000-070000000005', 2, 'text', 'How it works', 'Use the power rule on each polynomial term: multiply by the exponent, then reduce the exponent by one.', null),
  ('00000000-0000-4000-8000-080000000016', '00000000-0000-4000-8000-070000000005', 3, 'text', 'Look a little closer', 'A constant such as 7 has derivative 0, because it does not change with x.', null),
  ('00000000-0000-4000-8000-080000000017', '00000000-0000-4000-8000-070000000005', 4, 'worked_example', 'Worked example', 'd/dx (x³ + 2x) = 3x² + 2.', null),
  ('00000000-0000-4000-8000-080000000018', '00000000-0000-4000-8000-070000000006', 1, 'key_point', null, 'A derivative measures the instantaneous rate of change.', null),
  ('00000000-0000-4000-8000-080000000019', '00000000-0000-4000-8000-070000000006', 2, 'key_point', null, 'The power rule is d/dx (xⁿ) = nxⁿ⁻¹.', null),
  ('00000000-0000-4000-8000-08000000001a', '00000000-0000-4000-8000-070000000006', 3, 'key_point', null, 'Differentiate each term of a polynomial separately.', null),
  ('00000000-0000-4000-8000-08000000001b', '00000000-0000-4000-8000-070000000006', 4, 'worked_example', 'Worked example', 'd/dx (x³ + 2x) = 3x² + 2.', null);
insert into public.questions (id, origin, prompt, explanation, hints, subject_id, grade_id, difficulty, status, is_demo) values
  ('00000000-0000-4000-8000-090000000001', 'original_practice', 'If f(x) = 3x + 2, what is f(2)?', 'f(2) = 3(2) + 2 = 8.', array['Replace x with 2 in the rule.', 'Multiply 3 × 2 before adding 2.']::text[], '00000000-0000-4000-8000-030000000001', '00000000-0000-4000-8000-010000000004', 1, 'published', true),
  ('00000000-0000-4000-8000-090000000002', 'original_practice', 'For f(x) = x², what is f(-3)?', '(-3)² = 9.', array['Substitute -3 carefully.', 'A negative number squared becomes positive.']::text[], '00000000-0000-4000-8000-030000000001', '00000000-0000-4000-8000-010000000004', 1, 'published', true),
  ('00000000-0000-4000-8000-090000000003', 'original_practice', 'Which set lists the possible inputs of a function?', 'The domain is the set of values that can be used as inputs.', array['Think: input comes first.', 'The word for possible x-values is domain.']::text[], '00000000-0000-4000-8000-030000000001', '00000000-0000-4000-8000-010000000004', 1, 'published', true),
  ('00000000-0000-4000-8000-090000000004', 'original_practice', 'Find lim (x → 3) (2x + 1).', 'The limit is 7.', array['This function is continuous, so substitute x = 3.', 'Calculate 2(3) + 1.']::text[], '00000000-0000-4000-8000-030000000001', '00000000-0000-4000-8000-010000000004', 1, 'published', true),
  ('00000000-0000-4000-8000-090000000005', 'original_practice', 'Find lim (x → 2) x².', '2² = 4.', array['For x², direct substitution works.', 'Square 2.']::text[], '00000000-0000-4000-8000-030000000001', '00000000-0000-4000-8000-010000000004', 1, 'published', true),
  ('00000000-0000-4000-8000-090000000006', 'original_practice', 'If f is continuous at x = a, which is true?', 'Continuity requires lim(x→a) f(x) = f(a).', array['Continuity means no jump or hole at that point.']::text[], '00000000-0000-4000-8000-030000000001', '00000000-0000-4000-8000-010000000004', 2, 'published', true),
  ('00000000-0000-4000-8000-090000000007', 'original_practice', 'Differentiate x².', 'd/dx(x²) = 2x.', array['Use the power rule.', 'Bring the exponent down and reduce it by one.']::text[], '00000000-0000-4000-8000-030000000001', '00000000-0000-4000-8000-010000000004', 1, 'published', true),
  ('00000000-0000-4000-8000-090000000008', 'original_practice', 'Differentiate 5x.', 'd/dx(5x) = 5.', array['The slope of ax is a.']::text[], '00000000-0000-4000-8000-030000000001', '00000000-0000-4000-8000-010000000004', 1, 'published', true),
  ('00000000-0000-4000-8000-090000000009', 'original_practice', 'Differentiate x³ + x.', 'd/dx(x³ + x) = 3x² + 1.', array['Differentiate terms separately.']::text[], '00000000-0000-4000-8000-030000000001', '00000000-0000-4000-8000-010000000004', 2, 'published', true);
