insert into public.revision_cards (id, topic_id, kind, position, front, back, status, is_demo) values
  ('00000000-0000-4000-8000-0b0000000001', '00000000-0000-4000-8000-060000000001', 'concept', 1, 'What makes a rule a function?', 'Every permitted input gives exactly one output.', 'published', true),
  ('00000000-0000-4000-8000-0b0000000002', '00000000-0000-4000-8000-060000000001', 'flashcard', 2, 'Domain vs range', 'Domain: valid inputs. Range: the outputs produced.', 'published', true),
  ('00000000-0000-4000-8000-0b0000000003', '00000000-0000-4000-8000-060000000001', 'true_false', 3, 'True or false: x = 0 is in the domain of f(x) = 1/x.', 'False. Division by zero is not allowed.', 'published', true),
  ('00000000-0000-4000-8000-0b0000000004', '00000000-0000-4000-8000-060000000002', 'concept', 1, 'What does a limit describe?', 'The value a function approaches as the input gets close to a point.', 'published', true),
  ('00000000-0000-4000-8000-0b0000000005', '00000000-0000-4000-8000-060000000002', 'formula', 2, 'Continuity at x = a', 'lim(x→a) f(x) = f(a), with both sides defined.', 'published', true),
  ('00000000-0000-4000-8000-0b0000000006', '00000000-0000-4000-8000-060000000002', 'true_false', 3, 'True or false: a function must equal its limit at every point.', 'False. A function can have a hole where the limit still exists.', 'published', true),
  ('00000000-0000-4000-8000-0b0000000007', '00000000-0000-4000-8000-060000000003', 'formula', 1, 'Power rule', 'd/dx (xⁿ) = n·xⁿ⁻¹', 'published', true),
  ('00000000-0000-4000-8000-0b0000000008', '00000000-0000-4000-8000-060000000003', 'concept', 2, 'What does a derivative measure?', 'The instantaneous rate of change: the slope of the curve at a point.', 'published', true),
  ('00000000-0000-4000-8000-0b0000000009', '00000000-0000-4000-8000-060000000003', 'multiple_choice', 3, 'd/dx (7) = ?', '0. A constant does not change with x.', 'published', true);
